// Temporary diagnostic: measure navbar title font-size and each nav-item's active border box.
import { chromium } from 'playwright'
import { mockGetInfo, mockDeptTreeInPermission } from './home-v2-mocks.js'

const BASE_URL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8101'
const API_PREFIX = '/api/v2.0'
const VIEWPORT = { width: 1920, height: 1110 }
const NAV_TITLES = [
  '工作中心', '数据大屏', '行业管理', '项目管理', '业主自治',
  '共有资金', '阳光物业', '公共查询', '设施设备', '公共信息查询'
]
const menuRouters = NAV_TITLES.map((title, index) => ({
  name: `NavbarRoot${index}`,
  path: index === 0 ? '/index' : `/navbar-${index}`,
  hidden: false,
  component: 'Layout',
  meta: { title },
  children: [{ name: `NavbarPage${index}`, path: 'index', component: 'home/index', meta: { title: `${title}页面`, icon: 'dashboard' } }]
}))
const jsonResponse = (body, status = 200) => ({ status, contentType: 'application/json', body: JSON.stringify(body) })

async function installMocks(context) {
  await context.route(`**${API_PREFIX}/**`, async (route) => {
    const pathname = new URL(route.request().url()).pathname
    if (pathname.includes('/system/platformConfig/getInfo')) {
      return route.fulfill(jsonResponse({ code: 200, msg: 'ok', data: { region: '320500', platformName: '苏住房智慧物业管理平台', sysLogo: '/assets/images/logo-white.png' } }))
    }
    if (pathname.includes('/system/dept/treeInPermission')) return route.fulfill(jsonResponse(mockDeptTreeInPermission))
    if (pathname.includes('/menu/listRouters')) return route.fulfill(jsonResponse({ code: 200, msg: 'ok', data: menuRouters }))
    if (pathname.endsWith('/getInfo')) return route.fulfill(jsonResponse(mockGetInfo))
    if (pathname.includes('/secret') || pathname.includes('/captcha')) return route.fulfill(jsonResponse({ code: 500, msg: 'skip' }))
    return route.fulfill(jsonResponse({ code: 200, msg: 'ok', data: [], rows: [], total: 0 }))
  })
  await context.addInitScript(() => {
    const og = sessionStorage.getItem.bind(sessionStorage)
    Object.defineProperty(sessionStorage, 'getItem', { configurable: true, value(k) { return k === 'Admin-Token' ? 'e2e-mock-token' : og(k) } })
    localStorage.setItem('layout-setting', JSON.stringify({ topNav: true, tagsView: true, fixedHeader: true, sidebarLogo: true }))
  })
}

async function measureAt(page, label) {
  return await page.evaluate((label) => {
    const round = (n) => Math.round(n * 100) / 100
    const titleEl = document.querySelector('.title')
    const titleCs = titleEl ? getComputedStyle(titleEl) : null
    const items = [...document.querySelectorAll('.top-nav .nav-item')]
    const rows = items.map((el) => {
      const beforeCs = getComputedStyle(el, '::before')
      const rect = el.getBoundingClientRect()
      const text = el.querySelector('.nav-text')
      const textCs = text ? getComputedStyle(text) : null
      return {
        title: el.querySelector('.nav-text')?.textContent?.trim(),
        active: el.classList.contains('active'),
        itemWidth: round(rect.width),
        beforeWidth: beforeCs.width,
        beforeHeight: beforeCs.height,
        beforeBorder: beforeCs.borderWidth,
        beforeOpacity: beforeCs.opacity,
        textFontSize: textCs?.fontSize,
        textFontWeight: textCs?.fontWeight
      }
    })
    return {
      label,
      title: titleEl?.textContent?.trim(),
      titleFontSize: titleCs?.fontSize,
      titleFontWeight: titleCs?.fontWeight,
      titleLineHeight: titleCs?.lineHeight,
      titleFontFamily: titleCs?.fontFamily,
      navItems: rows
    }
  }, label)
}

async function main() {
  const browser = await chromium.launch({ headless: true })
  const context = await browser.newContext({ viewport: VIEWPORT, deviceScaleFactor: 1 })
  await installMocks(context)
  const page = await context.newPage()
  await page.goto(`${BASE_URL}/#/index`, { waitUntil: 'domcontentloaded', timeout: 120000 })
  await page.locator('.navbar').waitFor({ state: 'visible', timeout: 60000 })
  await page.waitForFunction((c) => document.querySelectorAll('.top-nav .nav-item').length === c, NAV_TITLES.length, { timeout: 60000 })
  await page.evaluate(() => document.fonts.ready.then(() => true))
  await page.waitForTimeout(400)

  const results = []
  results.push(await measureAt(page, 'initial(工作中心 active)'))

  // 逐个切换每个 item 为激活态，测量其 ::before 边框盒
  const n = await page.locator('.top-nav .nav-item').count()
  for (let i = 1; i < n; i++) {
    await page.locator('.top-nav .nav-item').nth(i).click()
    await page.waitForTimeout(250)
    const m = await measureAt(page, `active=#${i}`)
    // 仅保留激活项与标题信息以压缩输出
    results.push({ label: m.label, titleFontSize: m.titleFontSize, activeItem: m.navItems.find(r => r.active) })
  }

  console.log(JSON.stringify({ title: results[0].title, titleFontSize: results[0].titleFontSize, titleFontWeight: results[0].titleFontWeight, titleLineHeight: results[0].titleLineHeight, titleFontFamily: results[0].titleFontFamily, initialAllItems: results[0].navItems, activeSweep: results.slice(1) }, null, 2))
  await browser.close()
}

main().catch((e) => { console.error(e); process.exitCode = 1 })

